module tb_TopModule;
    logic       clk;
    logic       reset;
    logic [7:0] d;
    logic [7:0] q;

    TopModule uut (
        .clk(clk),
        .reset(reset),
        .d(d),
        .q(q)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 1;
        d = 8'hA5;
        #12;

        if (q !== 8'h00) begin
            $display("SELFTEST FAIL: Reset failed, q=%h", q);
            $finish;
        end

        reset = 0;
        d = 8'h3C;
        #10;
        if (q !== 8'h3C) begin
            $display("SELFTEST FAIL: Expected 3C, got %h", q);
            $finish;
        end

        d = 8'hFF;
        #10;
        if (q !== 8'hFF) begin
            $display("SELFTEST FAIL: Expected FF, got %h", q);
            $finish;
        end

        // Test synchronous reset while clocking
        reset = 1;
        d = 8'h55;
        #10;
        if (q !== 8'h00) begin
            $display("SELFTEST FAIL: Sync reset failed during clocking, q=%h", q);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
